{
    double a, b, c;
    double x1, x2;
    double delta;

    printf("Podaj liczby a, b i c:\n");
    printf("a = ");
    scanf("%lf", &a);
    printf("b = ");
    scanf("%lf", &b);
    printf("c = ");
    scanf("%lf", &c);

    delta = b*b - 4*a*c;

    if (delta > 0)
    {
        x1 = (-1*b +  sqrt(delta))/2*a;
        x2 = (-1*b -  sqrt(delta))/2*a;
