    if (delta == 0)
    {
        x1 = (-1*b)/2*a;
        printf("Miejsce zerowe funkcji f(x) = %.1lf x^2 + %.1lf x + %.1lf , x = %.1lf", a,  b, c, x1);
    }

    if (delta < 0)
        printf("Brak miejsc zerowych.");

    return 0;
