int factorial(struct NUMBER *a, struct NUMBER *b) {

    if(getSign(a) == -1){ 
        return -2;
    }

    struct NUMBER tmp1, tmp2, num;
    setInt(&num, 1);
    int flag = 0;

    clearByZero(b);

    while(1){
        if(flag == 0){
            flag++;
            increment(&num, &tmp1);
            multiple(&num, &tmp, b);
            copyNumber(&tmp, &num);
        } else {
            increment(&num, &tmp1);
            multiple(b, &tmp1, &tmp2);
            copyNumber(&tmp2, b);
        }

        if(numComp(&tmp1, a) == 0){ 
            break;
        }
    }

    return 0;




