int multiple(struct NUMBER *a, struct NUMBER *b, struct NUMBER *c) {
    int i, j, h, e, aj, bi;
    struct NUMBER tmp, d;



    clearByZero(c);
    dispNumberZeroSuppress(a);
    dispNumberZeroSuppress(b);

    for (i = 0; i < KETA;i++){
        printf("iã¯ããã§ãã%d\n", i);
        bi = b->n[i];
        h = 0;
        clearByZero(&d);
        for (j = 0; j < KETA;j++){
            aj = a->n[j];
            printf("aj:%d\nbi%d\n", aj, bi);





            e = aj * bi + h; 
            printf("e:%d\n", e); 
            if(j + i < KETA){
                d.n[j + i] = (e % 10); 
                printf("dl:");
                dispNumberZeroSuppress(&d);
                puts("");
                e /= 10;
                h = e; 
            }
        }

        if(h != 0){ 
            return -1;
        }
        printf("c:");
        dispNumberZeroSuppress(c);
        printf("d:");
        dispNumberZeroSuppress(&d);
        puts("");
        add(c, &d, &tmp);
        copyNumber(&tmp, c);
    }



    return 0; 
