void *count_vowels(void *string);

int main()
{

    char str[SIZE];
    printf("enter the string\n");
    int i,n=0;
    fgets(str,sizeof(str),stdin);
    for(i=1;str[i]!='\0';i++)
        {
        n++;
        }
    printf("the number of character in the string is %d\n",n);
    pthread_t thread;
