    pthread_join(thread,NULL);

    return 0;
}

void *count_vowels(void *string)

{
    char *b=(char *)string;
    int n,i,vowel=0;
    char ch;
    n=strlen(b);
    while(i<=n)
        {
            ch=b[i];
            if(ch=='a'||ch=='e'||ch=='i'||ch=='o'||ch=='u'||ch=='A'||ch=='E'||ch=='I'||ch=='O'||ch=='U')
            {vowel++;}
            i++;
        }
        printf("the number of vowels in the strings is  %d\n",vowel);
        return 0;
