    newnode->data=inp;
    newnode->next=NULL;
    return newnode;
}
void insert(node** head, int inp)
{
    node* linklist=createnode(inp);
    linklist->next=*head;
    *head=linklist;
    printf("%d inserted\n",(*head)->data);
}
void removeeven(node** head)
{
    while((*head)!=NULL && (*head)->data%2==0)
        *head=(*head)->next;
    node* h=*head;
    if((*head)==NULL)
        return;
    while(h->next!=NULL)
    {
        if(h->next->data%2==0)
            h->next=h->next->next;
        else
            h=h->next;
    }
}
