void selectionSort(int arr[], int len){ 
    int min,i,j,t;
    for(i=0;i<len-1;i++)
    {
        min=i;   
        for(j=i+1;j<len;j++)   
        {
            if(arr[j]<arr[min])
                min=j;;
        }
        t=arr[i];
        arr[i]=arr[min];   
        arr[min]=t;
        printf("Pass %d: ",i+1); 
        printArray(arr,len);   
    }
}
