int PowerI(int X, int Y)
{
    int Result = 1;
    while(Y != 0)
    {
        Result = Result * X;
        Y--;
    }
    return Result;
}

int PowerR(int X, int Y)
{
    static int Result = 1;
    if(Y != 0)
    {
        Result = Result * X;
        Y--;
        PowerR(X,Y);
    }
    return Result;
}

