void do_binar(int n, int sys){
    int r;
    if(sys < 2 || sys > 10){
        printf("Podano system liczbowy spoza zakresu!!!");
        return;
    }

    r = n % sys;
    if(n >= sys)
        do_binar(n / sys, sys);
    putchar('0' + r);
    return;
}
