}

void * thread_autobus(void * args) {
    while (1) {

        Autobus_En_Parada();

        Conducir_Hasta_Siguiente_Parada();
    }
}

void * thread_usuario(int i) {
    int id_usuario, a, b;
    id_usuario = i;

    while (1) {
        a=rand() % N_PARADAS;
        do{
            b=rand() % N_PARADAS;
