    long int n[200000], maior = 0, n0, vet[10000];

    scanf("%i", &t);

    for (int i = 0; i < t; i++)
    {
        scanf("%li", &n[i]);

        if (n[i] > maior)
            maior = n[i];
    }

    tam = primos(maior, vet);

    for  (int i = 0; i < t; i++)
    {
        primovf = primo(n[i], vet, tam);

        n0 = n[i];

        while (primovf == true && n[i] >= 10)
        {
            n[i] /= 10;

            primovf = primo(n[i], vet, tam);
        }

        if (primovf == true)
            printf("S\n");

        else if (primovf == false)
            printf("N\n");
    }    

    return 0;
