int isFileExists(const char *path)
{

    FILE *fptr = fopen(path, "r");


    if (fptr == NULL)
        return 0;


    fclose(fptr);

    return 1;
}




int isFileExistsAccess(const char *path)
{

    if (access(path, F_OK) == -1)
        return 0;

    return 1;
}




int isFileExistsStats(const char *path)
{
    struct stat stats;

    stat(path, &stats);


    if (stats.st_mode & F_OK)
        return 1;

    return 0;
}
