void swap_func(deck_node_t **deck, deck_node_t *node1, deck_node_t *node2)
{
    deck_node_t *tmp;

    if (node1->next == node2)
    {
        if (node2->next)
            node2->next->prev = node1;
        node2->prev = node1->prev;
        node1->next = node2->next;
        node2->next = node1;
        if (node1->prev)
            node1->prev->next = node2;
        node1->prev = node2;
        if (*deck == node1)
            *deck = node2;
    }
    else
    {
        node1->next->prev = node2;
        if (node1->prev)
            node1->prev->next = node2;
        node2->prev->next = node1;
        if (node2->next)
            node2->next->prev = node1;
        tmp = node1->next;
        node1->next = node2->next;
        node2->next = tmp;
        tmp = node2->prev;
        node2->prev = node1->prev;
        node1->prev = tmp;
        if (*deck == node1)
            *deck = node2;
    }
}

