    p = pivot->card->kind;
    i = lo;
    for (j = lo; j < hi; j++)
    {
        for (k = 0; s[k] != pj->card->value[0]; k++)
            ;
        for (v = 0; s[v] != pivot->card->value[0]; v++)
            ;
        if ((pj->card->kind < p) || (pj->card->kind == p && k <= v))
        {
            if (pi != pj)
            {
                swap_func(deck, pi, pj);
                tmp = pi;
                pi = pj;
                pj = tmp;
            }
            pi = pi->next, i++;
        }
        pj = pj->next;
    }
    if (pi != pivot)
        swap_func(deck, pi, pivot);
    return (i);
}

void quicksort(deck_node_t **deck, int lo, int hi)
{
