int get_numbers(int n, int max, int ns[], int i){
  int r = n - max;
  int check;

  if(i == 10)
    return 0;

  if(r < 10 && check_number(r, ns, i)){
    ns[i] = max;
    i++;
    if(check_number(r, ns, i)){
    ns[i] = r;
    return 1;
      }
    else{
      check = get_numbers(r, max-1, ns, i);
    }
  }
  else{
    ns[i] = max;
    i++;
    check = get_numbers(r, max-1, ns, i);
  }
  return (max == 9)? valid_array(ns, n): check;
}


int check_number(int n, int ns[], int i){
  for(int j = 0; j <= i; j++)
    if( n == ns[j])
      return 0;
  return 1;
