    for (char cur = fgetc(f); cur != EOF; cur = fgetc(f)) {
        if (cur == ':') switch (curs[0] + curs[1] + curs[2]) {
            case 333: { 
                size_t n = 0;
                char *field = get_field(&n, f);
                char *tmp = NULL;
                int byr = strtol(field, &tmp, 10);
                if (1920 <= byr && byr <= 2002)
