{
  printf("Ready for firmware over-the-air update\n");
}

static inline void DemoFOTAUpdateWorkflowEngine_restarting_EntryAction(DemoFOTAUpdateWorkflowEngine__data_t *instance)
{
  printf("Waiting for restart\n");
}
