int unija(pozicija p, pozicija q, pozicija r)
{
    while (p->next != NULL && q->next != NULL)
    {
        pozicija s = NULL;
        s = (pozicija)malloc(sizeof(struct lista));
        if (s == NULL)
        {
            printf("Neuspjesna alokacija memorije!\n");
            return 1;
        }
        s->next = NULL;
        if (p->next->el == q->next->el) 
        {
            s->el = p->next->el;
            p = p->next;
            q = q->next;
        }
        else if(p->next->el < q->next->el) 
        {
            s->el = p->next->el;
            p = p->next;
        }
        else
        {
            s->el = q->next->el;
            q = q->next;
        }
        r->next = s;
        r = s;
    }
    if (p->next == NULL) 
    {
        while (q->next != NULL)
        {
            pozicija s = NULL;
            s = (pozicija)malloc(sizeof(struct lista));
