            {
                printf("Neuspjesna alokacija memorije!\n");
                return 1;
            }
            s->next = NULL;
            s->el = q->next->el;
            q = q->next;
            r->next = s;
            r = s;
        }

    }
    else 
    {
        while (p->next != NULL)
        {
            pozicija s = NULL;
