            }
            s->next = NULL;
            s->el = p->next->el;
            p = p->next;
            r->next = s;
            r = s;
        }

    }

    return 0;
}
int presjek(pozicija p, pozicija q, pozicija r)
{
    while (p->next != NULL && q->next != NULL) 
    {
        if (p->next->el == q->next->el)
        {
            pozicija s = NULL;
            s = (pozicija)malloc(sizeof(struct lista));
            if (s == NULL)
            {
