{

    struct Queue* queue=createQueue(10000);
    enqueue(queue,src);
    int count=0;
    while(!isEmpty(queue))
    {

        int p=dequeue(queue);
        visited[p]=1;
        printf("%d ",p);

        count+=1;
        FOR(i,0,v)
        {
            if(graph[p][i])
            {
                if(!visited[i])
                {

                    enqueue(queue,i);
                }
            }
        }
    }
    return;
}
int main()
{
    int v;
    scanf("%d",&v);
    int** graph=makeGraph(v);
    int* visited=(int* )malloc(v*sizeof(int));\
    FOR(i,0,v)
        visited[i]=0;

    FOR(i,0,v)
    {
        if(!visited[i])
        {
            bfs(graph,visited,v,i);
            printf("\n");
        }
    }
    return 0;
