typedef struct
{
    char *c[20];
    int front;
    int rear;
}queue;

void enqueueright(queue *q,char* n)
{
    if (q->rear == 20)
        printf("Side Full\n");
    else
        q->c[(q->rear)++]=n;
}

void enqueueleft(queue *q,char* n)
{
    if (q->front == 0)
        printf("Side Full\n");
    else
        q->c[--(q->front)]=n;
}

void dequeueleft(queue *q)
{
    if (q->front==q->rear)
        printf("Queue Empty");

    else
        printf("\n%s deleted", q->c[(q->front)++] );

}

void dequeueright(queue *q)
{
    if (q->front==q->rear)
        printf("Queue Empty");

    else
        printf("\n%s deleted", q->c[--(q->rear)] );
}

void display(queue *q)
{
    int i;

    for (i = q->front ; i<q->rear ; i++)
        printf("%s\t",q->c[i]);

    printf("\n");
}

