int selectionSort(int x[], int n)
{
    int i,j,temp,flag = 0;
    for(i=0;i<n;i++)
    {
        for(j=i+1;j<n;j++)
        {
            if(x[i] > x[j])
            {
                temp = x[j];
                x[j] = x[i];
                x[i] = temp;
                flag = 1;
            }
        }
        if(flag == 0)
        {
            break;
        }
    }
    printf("sorted array:\n");
    for(i=0;i<n;i++)
    {
        printf("%d\n",x[i]);
    }
}
