      return ERROR_INVALID_PARAMETER;


   n = osStrlen(banner);


   if(n > SHELL_SERVER_BUFFER_SIZE)
      return ERROR_INVALID_LENGTH;


   osStrncpy(session->buffer, banner, n);


   session->bufferLen = n;
   session->bufferPos = 0;


   return NO_ERROR;
